import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Return one priority for each feasible bin.

    ``bins`` contains remaining capacities after filtering bins that cannot
    hold ``item``.  The evaluator selects the first maximum priority and
    opens a new bin when the array is empty.
    """
    residual = bins - item
    n = residual.size
    if n == 0:
        return np.zeros(0, dtype=np.float64)
    order = np.argsort(residual, kind="stable")
    ranks = np.empty(n, dtype=np.float64)
    ranks[order] = np.arange(n, dtype=np.float64)
    if n == 1:
        return np.zeros(1, dtype=np.float64)
    p = ranks / (n - 1)
    # Concave map: favors lower-than-median residuals but keeps gradation.
    return 1.0 - np.sqrt(p)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Return one priority for each feasible bin.

    ``bins`` contains remaining capacities after filtering bins that cannot
    hold ``item``.  The evaluator selects the first maximum priority and
    opens a new bin when the array is empty.
    """
    residual = bins - item
    if residual.size == 0:
        return np.zeros(0, dtype=np.float64)
    offset = 0.25
    return -np.abs(residual - offset)

